#nullable enable // autogenerated

using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.largeArrow)]
    public class LargeArrow : EntityBehaviourDefinition
    {
        public LargeArrow(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostHitEntityCallback);
        }
        public override void Update(Entity projectile)
        {
            base.Update(projectile);
            projectile.Velocity += projectile.Velocity.normalized * 0.3f;

            var rotation = projectile.RenderRotation;
            var quaternion = Quaternion.Euler(rotation);
            var axis = quaternion * Vector3.right;
            var rotate = Quaternion.AngleAxis(projectile.Velocity.magnitude * 15, axis);
            var newRotation = rotation + rotate.eulerAngles;
            newRotation.x %= 360;
            newRotation.y %= 360;
            newRotation.z %= 360;
            projectile.RenderRotation = newRotation;
        }
        private void PostHitEntityCallback(VanillaLevelCallbacks.PostProjectileHitParams param, CallbackResultVoid result)
        {
            var hitResult = param.hit;
            var projectile = hitResult.Projectile;
            if (!projectile.Definition.HasBehaviour(this))
                return;
            var damage = param.damage;
            if (damage == null)
                return;
            if (damage.HasAnyNotFatal())
            {
                projectile.Remove();
                return;
            }
            float overflowDamage = damage.GetFinalOverflowAmount();
            if (overflowDamage <= 0)
            {
                projectile.Remove();
                return;
            }
            projectile.SetDamage(overflowDamage);
        }
    }
}
